// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Step 1: Initialize the contract (requires initializer call)
        // We need to initialize the contract before any other calls
        // The initialize function is external and requires a specific caller context
        // Since we cannot directly call initialize in this test setup due to its modifiers,
        // we deploy a helper to simulate the initialization
        // But the instructions say interact ONLY through c
        // So we need to find an alternative path

        // Actually, the contract uses Initializable, so we can call initialize directly
        // Let's set up the prerequisite state
        vm.deal(address(c), 1 ether);

        // Initialize the contract with dummy parameters
        // credChainId, credId, verificationType, protocolFeeDestination
        // We'll use address(this) as protocolFeeDestination for simplicity
        c.initialize(1, 1, "signature", address(this));

        // Now the contract is initialized, and owner is address(this) (the test contract)
        // The test contract is the owner since we called initialize from the test contract

        // Step 2: Transfer ownership to a specific address (address(2))
        // As the current owner, we can transfer ownership
        address newOwner = address(2);
        c.transferOwnership(newOwner);

        // Step 3: Now pendingOwner = address(2)
        // In the reference contract, owner() still returns the original owner (this contract)
        // In the buggy contract, owner() returns address(1) always

        // Step 4: The pending owner (address(2)) tries to call acceptOwnership()
        // In the reference: owner() returns address(this), acceptOwnership checks if msg.sender == pendingOwner,
        //   then calls _transferOwnership which checks if msg.sender == owner() -> FAILS because msg.sender (address(2)) != owner (address(this))
        //   So acceptOwnership() reverts in reference
        // In the buggy: owner() returns address(1), acceptOwnership checks if msg.sender == pendingOwner (true),
        //   then calls _transferOwnership which checks if msg.sender == owner() -> address(2) != address(1) -> also reverts

        // Hmm, both revert. We need a scenario where they differ.

        // Let's think differently. The mutation makes owner() always return address(1).
        // acceptOwnership() in Ownable2StepUpgradeable calls pendingOwner() (which checks storage) then _transferOwnership
        // _transferOwnership in Ownable2StepUpgradeable deletes pendingOwner then calls super._transferOwnership
        // super._transferOwnership checks if msg.sender == owner(), then transfers

        // So for acceptOwnership() to succeed, msg.sender must equal owner() AND pendingOwner
        // In reference: owner() returns the actual owner
        // In buggy: owner() returns address(1)

        // If we set owner to address(1) via transferOwnership, then:
        // - Reference: owner() = address(1), pendingOwner = address(1) (after transfer completes)
        //   acceptOwnership from address(1): msg.sender == pendingOwner (true), msg.sender == owner() (true) -> success
        // - Buggy: owner() = address(1) always, actual owner might be different
        //   If actual owner is address(this), then transferOwnership to address(2) sets pendingOwner = address(2)
        //   acceptOwnership from address(2): msg.sender == pendingOwner (true), msg.sender == owner() -> address(2) != address(1) -> revert

        // Wait, but we need to compare two different contract versions. We can't run both in one test.
        // The test is supposed to pass on one version and fail on the other.
        // We'll write it so it passes on the reference (correct) version.

        // Let's set up a concrete case:
        // 1. Initialize (owner = this contract)
        // 2. Transfer ownership to address(1)
        // 3. From address(1), call acceptOwnership()
        // Reference: pendingOwner = address(1), owner() = this (before accept), after accept ownership moves to address(1)
        // Buggy: owner() always returns address(1), so acceptOwnership from address(1) will see msg.sender == pendingOwner (true) and msg.sender == owner() (true) -> success
        // But in reference, acceptOwnership from address(1) fails because owner() is this contract, not address(1)

        // Hmm, that's the opposite of what we want. We need reference to succeed and buggy to fail.

        // Let's try:
        // 1. Initialize (owner = address(this))
        // 2. Transfer ownership to address(this) itself? No, _transferOwnership in Ownable2Step deletes pendingOwner first.

        // Actually, let's trace more carefully:
        // transferOwnership(newOwner) sets pendingOwner = newOwner and emits event
        // acceptOwnership() :
        //   requires msg.sender == pendingOwner
        //   calls _transferOwnership(msg.sender) i.e., _transferOwnership(pendingOwner)
        //   _transferOwnership in Ownable2Step: delete pendingOwner, then super._transferOwnership(newOwner)
        //   super._transferOwnership: requires msg.sender == owner()  [this check is in OwnableUpgradeable]

        // So acceptOwnership() checks both pendingOwner and msg.sender == owner() (via _checkOwner)
        // Wait, no. The _transferOwnership function doesn't have a modifier, it's an internal function called from acceptOwnership.
        // The _checkOwner() check happens in the modifier only when called externally.

        // Let's look at the actual OpenZeppelin code:
        // acceptOwnership():
        //   address sender = _msgSender();
        //   if (pendingOwner() != sender) { revert OwnableUnauthorizedAccount(sender); }
        //   _transferOwnership(sender);
        // _transferOwnership (Ownable2Step):
        //   delete $._pendingOwner;
        //   super._transferOwnership(newOwner);
        // _transferOwnership (Ownable):
        //   OwnableStorage storage $ = _getOwnableStorage();
        //   address oldOwner = $._owner;
        //   $._owner = newOwner;
        //   emit OwnershipTransferred(oldOwner, newOwner);
        // Wait, Ownable's _transferOwnership does NOT check msg.sender! It just sets the owner.
        // That means acceptOwnership() does NOT check the current owner at all!
        // It only checks that msg.sender is the pendingOwner.

        // So the difference isn't about acceptOwnership reverting.
        // The difference is about what owner() returns after operations.

        // Let's find a property that differs:
        // In reference: owner() returns the actual owner stored in storage
        // In buggy: owner() returns address(1) always

        // So we can assert on the return value of owner():
        // After initialization, owner() should be this contract in reference, but address(1) in buggy.

        // Let's do that:
        // 1. Initialize (owner = address(this))
        // 2. Call c.owner() and check it equals address(this)
        // In reference: passes
        // In buggy: fails (returns address(1))

        // That's a simple concrete test
        // But we need to ensure initialization works
        c.initialize(1, 1, "signature", address(this));

        // After initialization, owner should be address(this) in reference
        assertTrue(c.owner() == address(this), "Owner should be the contract itself after initialization");
    }
}

