pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Step 1: Initialize the contract (call initialize via factory-like setup)
        // Since C uses initializer, we need to mimic the factory initialization:
        // But the contract is deployed via new C(), which has _disableInitializers().
        // To make it usable, we call initialize with a dummy protocolFeeDestination (e.g., address(this)).
        vm.prank(address(0xdead)); // set initial owner to 0xdead
        c.initialize(1, 1, "", address(this));

        // Step 2: Transfer ownership to address(0x1) as the pending owner
        vm.prank(address(0xdead));
        c.transferOwnership(address(0x1));

        // Step 3: Now, an address that is NOT the pending owner (say 0x2) calls acceptOwnership()
        vm.prank(address(0x2));
        bool ok;
        try c.acceptOwnership() {
            ok = true; // bug: succeeds because owner() returns address(1) -> check passes
        } catch {
            ok = false; // reference: reverts with OwnableUnauthorizedAccount
        }

        // Assert: reference has ok = false, bug has ok = true
        assertTrue(!ok);
    }
}

