pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy and initialize with proper setup (minimal params to avoid revert)
        vm.prank(address(0xdead)); // arbitrary deployer
        c.initialize(1, 1, "test", address(0xbeef));

        // Transfer ownership to address(1)
        vm.prank(c.owner()); // current owner is 0xdead
        c.transferOwnership(address(1));

        // Now address(1) calls acceptOwnership
        vm.prank(address(1));
        c.acceptOwnership();

        // The reference contract will have owner = address(1)
        // The buggy contract will also have owner = address(1) (same result)
        // But we need a different divergence: after this, transfer ownership to address(2)
        // The reference will allow only address(1) to call transferOwnership (since it's owner)
        // The buggy contract returns address(1) from owner() always, so any caller can transfer

        // Let's try another scenario: the original owner (0xdead) tries to transfer again
        // In reference: 0xdead is no longer owner, so it reverts
        // In buggy: owner() returns address(1) regardless, so 0xdead is not owner either — but the check is `owner() != _msgSender()`
        // Buggy also reverts for 0xdead because owner() returns address(1), not 0xdead

        // Better scenario: check that after acceptOwnership, the new owner is correctly set
        // Reference: owner() returns address(1)
        // Buggy: owner() returns address(1) as well (same)

        // The key bug is that owner() always returns address(1). So if the real owner is something else,
        // the buggy contract's owner() still returns address(1).
        // We can check: after initialization, before any transfers, the real owner is the deployer (0xdead)
        // but buggy's owner() returns address(1).

        // Actually, the bug is *only* in owner() returning address(1) always.
        // So we should initialize and then check owner() directly.
        // Reference: owner() == initial owner (msg.sender of initialize)
        // Buggy: owner() == address(1)

        // But to avoid the InvalidInitialization error, we must ensure proper initialization.
        // The constructor calls _disableInitializers, so we need to use a proxy or deploy properly.
        // With `new C()`, the contract is not a proxy, so UUPS functions may not work as expected.
        // Instead, we can test the bug directly on the logic contract.

        // The simplest concrete test: deploy, call initialize, then check owner()
        // For the buggy contract (where owner() returns address(1)), it will return address(1)
        // For the reference, it will return the deployer

        address initialOwner = c.owner();
        assertTrue(initialOwner == address(0xdead) || initialOwner == address(1));
        // Both possibilities: we need an assertion that differs.
        // The buggy code returns address(1) always, so initialOwner == address(1) for buggy.
        // The reference code returns the actual owner (which is address(this) because of Ownable init in constructor?)
        // Actually the constructor doesn't call __Ownable_init, it only calls _disableInitializers.
        // After deployment with new C(), there is no owner set (uninitialized).
        // So owner() returns address(0) in reference, address(1) in buggy.

        assertTrue(initialOwner == address(1)); // This passes on buggy, fails on reference (where owner is 0)
        // OR we can do:
        // assertTrue(initialOwner != address(1)); // passes on reference, fails on buggy

        // But we need reference to pass, buggy to fail.
        // Reference: initialOwner == address(0) (since no owner set yet)
        // Buggy: initialOwner == address(1)
        // So assertTrue(initialOwner != address(1)) passes reference, fails buggy

        assertTrue(initialOwner != address(1));
    }
}

