pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // First, initialize the contract via the constructor pattern: call initialize through the proxy
        // Since set up uses new C() directly (not proxy), we need to initialize.
        // The initialize function requires initializer modifier, so we call it once.
        vm.prank(address(this));
        c.initialize(1, 1, "test", address(0xdead));

        // The current owner is address(this) after initialization.
        address newOwner = address(0x01);

        // Owner transfers ownership to address(1)
        vm.prank(address(this));
        c.transferOwnership(newOwner);

        // Now pendingOwner is address(1), owner() is still address(this) (reference) or always address(1) (bug)
        // Let address(1) call acceptOwnership:
        vm.prank(newOwner);
        bool ok;
        try c.acceptOwnership() {
            ok = true;
        } catch {
            ok = false;
        }

        // In the reference, owner() becomes address(1) after acceptOwnership, so ok is true.
        // In the bug, owner() always returns address(1) even before acceptOwnership, so 
        // the pendingOwner check (pendingOwner != msg.sender) fails because pendingOwner is address(1) and msg.sender is address(1),
        // but wait: in the bug, owner() returns address(1) and the _transferOwnership inside acceptOwnership sets owner to address(1)
        // Actually the bug only changes owner() view, not the internal storage. The acceptOwnership function reads owner() which returns address(1) in bug,
        // so the check (owner() == msg.sender) if called somewhere? No, acceptor checks pendingOwner.
        // Let's analyze: acceptOwnership checks if pendingOwner == msg.sender. pendingOwner is set to address(0x01) by transferOwnership.
        // In the bug, owner() always returns address(1). The _transferOwnership sets _owner to msg.sender (address(0x01)).
        // So it should succeed. But the already-tried scenarios indicate it fails. 
        // Actually the issue: after transferOwnership, pendingOwner = address(0x01). In reference, owner() is address(this).
        // In bug, owner() returns address(1). When address(0x01) calls acceptOwnership, in reference it succeeds (owner becomes 0x01).
        // In bug, acceptOwnership checks pendingOwner (0x01) == msg.sender (0x01) -> yes, so it proceeds to _transferOwnership which
        // sets _owner to msg.sender. But then owner() still returns address(1) due to bug.
        // So both succeed, but after that reference owner() returns 0x01, bug owner() returns address(1).
        // Assert that owner() returns address(0x01) only in reference.

        address ownerAfter = c.owner();
        assertTrue(ownerAfter == address(0x01), "Owner should be 0x01 in reference, but bug returns address(1)");
    }
}

