pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy with address(this) as owner (default from __Ownable_init(msg.sender) in initialize)
        // Actually initialize is external, so we must call it first
        // The constructor disables initializers, so we need to deploy via a minimal proxy or just call initialize
        // But the problem states 'new C()' deploys and we interact through c
        // Since C uses Initializable and constructor calls _disableInitializers, a direct new C() will not be initialized.
        // However, the test should demonstrate the difference in getRoyalties after acceptOwnership() is called.
        // For that to work, we need to initialize the contract first.
        // We'll call initialize() with dummy values to set up the contract.
        vm.startPrank(address(this));
        c.initialize(1, 1, "sig", address(this));
        vm.stopPrank();

        // Now call acceptOwnership() to transfer ownership to a specific address.
        // Since pendingOwner is set by transferOwnership, we first transfer ownership.
        address newOwner = address(0x1234);
        vm.prank(address(this));
        c.transferOwnership(newOwner);

        // Now newOwner calls acceptOwnership()
        vm.prank(newOwner);
        c.acceptOwnership();

        // After acceptOwnership, getRoyalties(0) should return the default configuration
        // The reference returns royaltyBPS=500, buggy returns 300.
        ICreatorRoyaltiesControl.RoyaltyConfiguration memory config = c.getRoyalties(0);
        assertTrue(config.royaltyBPS == 500, "royaltyBPS should be 500 in reference");
    }
}

