import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initialize the contract through the required upgradeable pattern
        // We need to call initialize on the contract
        // First, deploy a proxy? No, we need to properly initialize the contract
        // Since C uses Initializable, we need to call initialize directly
        // But C inherits from many base contracts and needs certain setup
        // The simplest approach: we can simulate the initialization by calling
        // the internal functions through a public initialization? No.
        // We'll use a workaround: deploy a minimal proxy or use vm.prank
        // Actually, we can just initialize the contract manually
        // C inherits from Ownable2StepUpgradeable, so we can call transferOwnership
        // But first we need to initialize royalties
        // Let's check: initializeRoyalties is internal, so we can't call it directly
        // However, the contract already has an initialize() function that does this
        // We need to call initialize with proper parameters
        // But initialize() requires credChainId, credId, verificationType, protocolFeeDest
        // Let's call it
        vm.prank(address(0xdead));
        // Actually, initialize() calls __Ownable_init(msg.sender), so the deployer becomes owner
        // Since setUp() deployed c, the owner of c is address(this) (the test contract)
        // We need to call initialize() from the test contract
        c.initialize(1, 1, "test", address(this));

        // Now ownership is with address(this). Let's transfer ownership to a new address
        address newOwner = address(0x1234);
        c.transferOwnership(newOwner);

        // Now newOwner must accept ownership
        vm.prank(newOwner);
        c.acceptOwnership();

        // After acceptOwnership(), getRoyalties for token 0 should show default
        // Reference: royaltyBPS = 500, Buggy: royaltyBPS = 300
        // Read the royaltyBPS value
        (uint32 royaltyBPS, ) = c.getRoyalties(0);
        assertTrue(royaltyBPS == 500, "Default royaltyBPS should be 500");
    }
}

