pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initialize the contract via the onlyPhiFactory — we simulate by calling initialize directly (since it's external).
        // The initialize function sets the royalty recipient via initializeRoyalties(protocolFeeDestination_).
        // We need to call initialize with a non-zero protocolFeeDestination_ to initialize royalties.
        vm.prank(address(0xdead));  // phiFactory will be msg.sender
        c.initialize(1, 1, "test", address(0x1234));

        // Now getRoyalties(0) should return the default (royaltyBPS=500 in ref, 300 in bug).
        // But first we need to have a tokenId 0 — note royalties mapping starts empty.
        // The default is returned when royalties[0] is all zeros (royaltyRecipient = address(0)).
        // So we don't need to call acceptOwnership; the test fails because the default itself differs.
        // However the problem statement says driven through acceptOwnership(), so we add a call to acceptOwnership after transferring ownership.

        // Transfer ownership to an arbitrary address to call acceptOwnership later.
        c.transferOwnership(address(0x9999));
        vm.prank(address(0x9999));
        c.acceptOwnership();

        // Now read getRoyalties(0)
        (uint32 bps, address rec) = c.getRoyalties(0);
        // The reference contract returns bps == 500, bug returns 300.
        assertTrue(bps == 500);
    }
}

