import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);

        // Initially, c's owner is the test contract (this).
        // Transfer ownership to alice.
        c.transferOwnership(alice);

        // Now alice attempts to accept ownership.
        bool ok = true;
        vm.prank(alice);
        try c.acceptOwnership() { ok = true; } catch { ok = false; }

        // In the correct version (P), acceptOwnership() succeeds and owner becomes alice.
        // In the buggy version (M), pendingOwner() returns address(0), so acceptOwnership() reverts (ok = false).
        assertTrue(ok);
    }
}

